const acceptancePhrases = new Set([
  'acepto',
  '/acepto',
  'si acepto',
  's\u00ed acepto',
  'estoy de acuerdo',
  'i agree',
  '/agree',
  'agree',
  'i accept',
  '/accept',
  'accept'
]);
const declinePhrases = new Set([
  'no acepto',
  '/no_acepto',
  'rechazo',
  'no estoy de acuerdo',
  'i do not agree',
  '/decline',
  'decline',
  'i decline',
  'reject',
  '/reject'
]);

const out = [];

for (const item of $input.all()) {
  const msg = item.json.message ?? {};
  const chatId = msg.chat?.id;
  const userId = msg.from?.id;
  const textSource = typeof msg.text === 'string'
    ? msg.text
    : (typeof msg.caption === 'string' ? msg.caption : '');
  const text = textSource.trim();
  const normalizedText = text.toLowerCase();
  const fileIdRaw = msg.video?.file_id || msg.document?.file_id;
  const fileId = typeof fileIdRaw === 'string' ? fileIdRaw.trim() : '';

  out.push({
    json: {
      chat_id: chatId,
      user_id: userId,
      text,
      normalized_text: normalizedText,
      is_acceptance: acceptancePhrases.has(normalizedText),
      is_decline: declinePhrases.has(normalizedText),
      file_id: fileId
    }
  });
}

return out;

const originalItem = $items('Interpretar mensaje de Telegram', 0, $itemIndex)?.[0]?.json ?? {};
const consentRecord = $json ?? {};

const chatId = originalItem.chat_id;
const userId = originalItem.user_id;
const currentFileId = originalItem.file_id;
const isAcceptance = originalItem.is_acceptance === true;
const isDecline = originalItem.is_decline === true;

const recordExists = consentRecord.telegram_user_id !== undefined && consentRecord.telegram_user_id !== null;
const consentStatus = typeof consentRecord.consent_status === 'string' ? consentRecord.consent_status : 'missing';
const pendingFileId = typeof consentRecord.pending_file_id === 'string' ? consentRecord.pending_file_id.trim() : '';
const pendingChatId = consentRecord.pending_chat_id ?? chatId;

if (!chatId || userId === undefined || userId === null) {
  return [{
    json: {
      chat_id: chatId,
      should_process: false,
      persist_mode: 'none',
      response_text: 'No pude verificar tu ID de Telegram, as\u00ed que no puedo continuar.'
    }
  }];
}

if (consentStatus === 'accepted') {
  if (currentFileId) {
    return [{
      json: {
        chat_id: chatId,
        user_id: userId,
        file_id: currentFileId,
        should_process: true,
        persist_mode: 'none'
      }
    }];
  }

  if (isAcceptance) {
    return [{
      json: {
        chat_id: chatId,
        user_id: userId,
        should_process: false,
        persist_mode: 'none',
        response_text: 'Tu autorizaci\u00f3n para el uso y tratamiento de datos personales ya se encuentra vigente para esta cuenta de Telegram. Puedes enviar tu video cuando lo desees.'
      }
    }];
  }

  return [{
    json: {
      chat_id: chatId,
      user_id: userId,
      should_process: false,
      persist_mode: 'none',
      response_text: 'Tu autorizaci\u00f3n para el tratamiento de datos personales se encuentra vigente. Env\u00eda un video para continuar con el servicio.'
    }
  }];
}

if (isAcceptance) {
  const fileToProcess = currentFileId || pendingFileId;
  const processingChatId = currentFileId ? chatId : pendingChatId;

  return [{
    json: {
      chat_id: chatId,
      user_id: userId,
      file_id: fileToProcess,
      process_chat_id: processingChatId,
      should_process: Boolean(fileToProcess),
      persist_mode: recordExists ? 'update' : 'create',
      consent_status: 'accepted',
      pending_file_id: null,
      pending_chat_id: null,
      response_text: fileToProcess
        ? 'Tu autorizaci\u00f3n para el uso y tratamiento de datos personales ha sido registrada. Procederemos con el tratamiento del video pendiente conforme a las finalidades informadas.'
        : 'Tu autorizaci\u00f3n para el uso y tratamiento de datos personales ha sido registrada correctamente. Ahora puedes enviar tu video para continuar con el servicio.'
    }
  }];
}

if (isDecline) {
  return [{
    json: {
      chat_id: chatId,
      user_id: userId,
      should_process: false,
      persist_mode: recordExists ? 'update' : 'create',
      consent_status: 'declined',
      pending_file_id: null,
      pending_chat_id: null,
      response_text: 'Lamentablemente, el consentimiento es obligatorio para usar nuestra aplicaci\u00f3n. Esperamos poder ayudarte en el futuro.'
    }
  }];
}

if (consentStatus === 'declined') {
  return [{
    json: {
      chat_id: chatId,
      user_id: userId,
      should_process: false,
      persist_mode: 'none'
    }
  }];
}

return [{
  json: {
    chat_id: chatId,
    user_id: userId,
    should_process: false,
    persist_mode: recordExists ? 'update' : 'create',
    consent_status: 'pending',
    pending_file_id: currentFileId || pendingFileId || null,
    pending_chat_id: currentFileId ? chatId : (pendingFileId ? pendingChatId : null),
    response_text: 'Para continuar, debes otorgar tu consentimiento libre, espec\u00edfico, informado e inequ\u00edvoco para el uso y tratamiento de tus datos personales y de los videos, im\u00e1genes, metadatos e informaci\u00f3n asociada que nos proporciones, para finalidades relacionadas con la prestaci\u00f3n del servicio, incluyendo su recolecci\u00f3n, registro, organizaci\u00f3n, conservaci\u00f3n, almacenamiento, consulta, uso, an\u00e1lisis, procesamiento, circulaci\u00f3n interna, transmisi\u00f3n y las dem\u00e1s operaciones estrictamente necesarias para la gesti\u00f3n del servicio y el cumplimiento de obligaciones legales aplicables. Asimismo, declaras haber sido informado de que puedes ejercer tus derechos de acceso, rectificaci\u00f3n, actualizaci\u00f3n, oposici\u00f3n, eliminaci\u00f3n y revocatoria del consentimiento conforme a la normativa vigente en Ecuador. Responde exactamente con ACEPTO para autorizar o NO ACEPTO para rechazar.'
  }
}];

const nowIso = new Date().toISOString();

return $input
  .all()
  .filter((item) => item.json.persist_mode === 'create')
  .map((item) => ({
    json: {
      telegram_user_id: item.json.user_id,
      chat_id: item.json.chat_id,
      consent_status: item.json.consent_status,
      pending_file_id: item.json.pending_file_id ?? null,
      pending_chat_id: item.json.pending_chat_id ?? null,
      accepted_at: item.json.consent_status === 'accepted' ? nowIso : null,
      declined_at: item.json.consent_status === 'declined' ? nowIso : null,
      updated_at: nowIso
    }
  }));

const nowIso = new Date().toISOString();

return $input
  .all()
  .filter((item) => item.json.persist_mode === 'update')
  .map((item) => ({
    json: {
      user_id: item.json.user_id,
      chat_id: item.json.chat_id,
      consent_status: item.json.consent_status,
      pending_file_id: item.json.pending_file_id ?? null,
      pending_chat_id: item.json.pending_chat_id ?? null,
      accepted_at: item.json.consent_status === 'accepted' ? nowIso : null,
      declined_at: item.json.consent_status === 'declined' ? nowIso : null,
      updated_at: nowIso
    }
  }));

return $input
  .all()
  .filter((item) => item.json.response_text)
  .map((item) => ({
    json: {
      chat_id: item.json.chat_id,
      response_text: item.json.response_text
    }
  }));

return $input
  .all()
  .filter((item) => item.json.should_process === true && item.json.file_id)
  .map((item) => ({
    json: {
      chat_id: item.json.process_chat_id || item.json.chat_id,
      user_id: item.json.user_id,
      file_id: item.json.file_id
    }
  }));
